/* Generated by scripts/split-content.mjs — do not edit by hand.
   The glossary and a sample of the question bank. The rest is served
   from the content function once entitlement is confirmed. */
window.DATA = {"cards":[{"id":"c000","term":"Voltage (E or V)","def":"Electrical pressure or potential difference that pushes current through a circuit. Measured in volts. Like water pressure in a pipe.","cat":"Theory"},{"id":"c001","term":"Current (I)","def":"The flow of electrons through a conductor. Measured in amperes (amps). Like the volume of water flowing through a pipe.","cat":"Theory"},{"id":"c002","term":"Resistance (R)","def":"Opposition to current flow. Measured in ohms (Ω). Determined by material, length, cross-sectional area, and temperature of the conductor.","cat":"Theory"},{"id":"c003","term":"Ohm's Law","def":"E = I × R. Voltage equals current times resistance. The fundamental relationship governing all electrical circuits.","cat":"Theory"},{"id":"c004","term":"Power (P)","def":"The rate of doing work. P = E × I (watts = volts × amps). Also P = I²R and P = E²/R.","cat":"Theory"},{"id":"c005","term":"Watt","def":"The unit of electrical power. One watt = one volt × one amp. 1,000 watts = 1 kilowatt (kW).","cat":"Theory"},{"id":"c006","term":"Kilowatt-Hour (kWh)","def":"A unit of energy consumption. 1 kW used for 1 hour. What the electric meter measures and the utility bills for.","cat":"Theory"},{"id":"c007","term":"AC vs. DC","def":"Alternating Current reverses direction cyclically (60 Hz in the US). Direct Current flows in one direction. Most building power is AC; batteries are DC.","cat":"Theory"},{"id":"c008","term":"Single-Phase Power","def":"Two hot conductors and a neutral, providing 120V (hot-to-neutral) and 240V (hot-to-hot). Standard residential service.","cat":"Theory"},{"id":"c009","term":"Three-Phase Power","def":"Three hot conductors with voltages 120° apart. More efficient for large motors and commercial loads. Delta and wye configurations.","cat":"Theory"},{"id":"c010","term":"Wye vs. Delta","def":"Wye (star): has a neutral point, provides two voltages (e.g., 208Y/120V or 480Y/277V). Delta: no neutral in a pure delta, higher power density.","cat":"Theory"},{"id":"c011","term":"Power Factor","def":"The ratio of real power (watts) to apparent power (VA). Ranges from 0 to 1. Inductive loads (motors) have lagging power factor. Corrected with capacitors.","cat":"Theory"},{"id":"c012","term":"Series Circuit","def":"Components connected end-to-end. Same current through all components. Voltages add up. Total resistance equals the sum of all resistances.","cat":"Theory"},{"id":"c013","term":"Parallel Circuit","def":"Components connected across the same two points. Same voltage across all branches. Currents add up. Total resistance is less than the smallest branch.","cat":"Theory"},{"id":"c014","term":"Conductor","def":"Material that allows electrons to flow easily. Copper and aluminum are standard in electrical wiring. Copper has lower resistance per unit length.","cat":"Theory"},{"id":"c015","term":"Insulation","def":"Non-conductive material surrounding a conductor to prevent shock, short circuits, and ground faults. Rated by temperature and environment.","cat":"Theory"},{"id":"c016","term":"Ampacity","def":"The maximum current a conductor can carry continuously without exceeding its temperature rating. Determined by conductor size, insulation type, and ambient conditions.","cat":"Theory"},{"id":"c017","term":"Voltage Drop","def":"The reduction in voltage along a conductor due to resistance. NEC recommends no more than 3% for branch circuits and 5% total from service to outlet.","cat":"Theory"},{"id":"c018","term":"Transformer","def":"A device that changes voltage levels using electromagnetic induction. Step-up increases voltage; step-down decreases it. Turns ratio determines the voltage ratio.","cat":"Theory"},{"id":"c019","term":"Impedance","def":"Total opposition to AC current flow, combining resistance and reactance. Measured in ohms. Includes both resistive and inductive/capacitive components.","cat":"Theory"},{"id":"c020","term":"Ground Fault","def":"An unintentional connection between an energized conductor and ground. Can cause shock, fire, or equipment damage. GFCIs detect and interrupt these faults.","cat":"Theory"},{"id":"c021","term":"Short Circuit","def":"An unintentional low-resistance connection between two conductors at different voltages. Produces very high current that can cause fire and equipment damage.","cat":"Theory"},{"id":"c022","term":"Overload","def":"Current exceeding the rated capacity of equipment or conductors. Less sudden than a short circuit but still dangerous. Causes overheating over time.","cat":"Theory"},{"id":"c023","term":"Arc Fault","def":"An unintended electrical discharge through an air gap, often caused by damaged wiring. Can ignite surrounding materials. AFCIs detect and interrupt these.","cat":"Theory"},{"id":"c024","term":"National Electrical Code (NEC)","def":"NFPA 70. The standard for electrical installation safety in the United States. Updated every three years. Adopted by states and municipalities as law.","cat":"NEC General"},{"id":"c025","term":"NEC Article 90","def":"Introduction and scope of the NEC. States the purpose: practical safeguarding of persons and property from hazards arising from the use of electricity.","cat":"NEC General"},{"id":"c026","term":"NEC Article 100","def":"Definitions. Contains the official definitions of terms used throughout the Code. Essential for interpreting any NEC requirement.","cat":"NEC General"},{"id":"c027","term":"NEC Article 110","def":"Requirements for electrical installations. Covers workspace clearances, equipment ratings, conductor termination temperatures, and working space.","cat":"NEC General"},{"id":"c028","term":"Listed vs. Labeled","def":"Listed: evaluated by a testing lab (UL, ETL) and found suitable for a specific purpose. Labeled: has the lab's label attached. NEC requires listed equipment.","cat":"NEC General"},{"id":"c029","term":"Authority Having Jurisdiction (AHJ)","def":"The entity responsible for enforcing the Code — typically the local building inspector or electrical inspector. The AHJ has final authority on interpretation.","cat":"NEC General"},{"id":"c030","term":"Working Space (110.26)","def":"Clear workspace required in front of electrical panels: 30 inches wide, 36 inches deep (for 0-150V), headroom of 6.5 feet. Panels must be accessible.","cat":"NEC General"},{"id":"c031","term":"Dedicated Equipment Space (110.26(E))","def":"The space above and below the panelboard extending to the ceiling. No piping, ducts, or unrelated equipment allowed in this zone.","cat":"NEC General"},{"id":"c032","term":"Conductor Temperature Rating","def":"Conductors and terminals have temperature ratings (60°C, 75°C, 90°C). Terminations are typically rated 75°C. Use the lower of the conductor or terminal rating for ampacity.","cat":"NEC General"},{"id":"c033","term":"NEC Chapter Layout","def":"Ch.1-4: General rules apply to all installations. Ch.5-7: Special occupancies, equipment, conditions modify or supplement Ch.1-4. Ch.8: Communications (standalone). Ch.9: Tables.","cat":"NEC General"},{"id":"c034","term":"NM Cable (Romex®)","def":"Non-metallic sheathed cable (NEC Article 334). Contains 2-3 insulated conductors and a bare ground inside a plastic jacket. Standard for residential branch circuits.","cat":"Wiring"},{"id":"c035","term":"MC Cable","def":"Metal-clad cable (Article 330). Conductors inside a metal armor. Used where more physical protection is needed than NM provides. Contains a bonding strip or ground.","cat":"Wiring"},{"id":"c036","term":"AC Cable (BX)","def":"Armored cable (Article 320). Interlocking metal armor with an internal bonding strip. The armor itself is not a grounding path.","cat":"Wiring"},{"id":"c037","term":"EMT (Electrical Metallic Tubing)","def":"Thin-wall conduit (Article 358). Lightweight, easy to bend. Connected with set-screw or compression fittings. Not threaded. Common in commercial work.","cat":"Wiring"},{"id":"c038","term":"RMC (Rigid Metal Conduit)","def":"Heavy-wall steel conduit (Article 344). Threaded connections. Maximum physical protection. Required in hazardous locations and areas subject to physical damage.","cat":"Wiring"},{"id":"c039","term":"IMC (Intermediate Metal Conduit)","def":"Medium-wall conduit (Article 342). Lighter than RMC, threaded. Approved for all locations where RMC is permitted.","cat":"Wiring"},{"id":"c040","term":"PVC Conduit","def":"Rigid polyvinyl chloride conduit (Article 352). Non-metallic, corrosion-resistant. Requires a separate equipment grounding conductor. Expansion fittings needed for temperature changes.","cat":"Wiring"},{"id":"c041","term":"ENT (Electrical Nonmetallic Tubing)","def":"Corrugated plastic tubing (Article 362). Flexible, lightweight. Used in concealed locations in buildings of specific construction types.","cat":"Wiring"},{"id":"c042","term":"Liquidtight Flexible Metal Conduit (LFMC)","def":"Flexible metal conduit with a liquid-tight jacket (Article 350). Used for connections to equipment that vibrates or requires flexibility in wet locations.","cat":"Wiring"},{"id":"c043","term":"Wireways","def":"Sheet metal or nonmetallic troughs with hinged covers (Articles 376, 378). Used where access to conductors is needed along the run. Max fill: 20% cross-section.","cat":"Wiring"},{"id":"c044","term":"Cable Tray","def":"A structural support system for cables (Article 392). Not a raceway or enclosure. Provides an open pathway for cables in industrial and commercial installations.","cat":"Wiring"},{"id":"c045","term":"Conductor Fill (Chapter 9, Table 1)","def":"The maximum percentage of conduit cross-section that can be filled with conductors: 53% for 1 conductor, 31% for 2, 40% for 3 or more.","cat":"Wiring"},{"id":"c046","term":"Box Fill Calculation (314.16)","def":"Each conductor, device, clamp, and ground counts toward the maximum volume a box can contain. Oversized boxes or ganged boxes used when fill is exceeded.","cat":"Wiring"},{"id":"c047","term":"Wire Gauge (AWG)","def":"American Wire Gauge. Smaller numbers = larger conductors. #14 is the smallest for general wiring (15A). #12 for 20A. #10 for 30A. Sizes above #4/0 use kcmil.","cat":"Wiring"},{"id":"c048","term":"Conductor Color Code","def":"Black, red, blue = ungrounded (hot). White or gray = grounded (neutral). Green or bare = equipment grounding. These are NEC standard identifications.","cat":"Wiring"},{"id":"c049","term":"Derating (Adjustment Factors)","def":"When more than 3 current-carrying conductors are in a raceway, or ambient temperature exceeds 86°F/30°C, ampacity must be reduced per NEC Tables 310.15(B) and (C).","cat":"Wiring"},{"id":"c050","term":"Splices and Connections","def":"All splices must be made in accessible junction boxes (NEC 300.15). Connections must be made with listed connectors (wire nuts, lugs, split bolts). No exposed splices.","cat":"Wiring"},{"id":"c051","term":"NEC Article 250","def":"Covers grounding and bonding of electrical systems and equipment. The most frequently tested NEC article on licensing exams.","cat":"Grounding"},{"id":"c052","term":"Grounding vs. Bonding","def":"Grounding: connecting to the earth to stabilize voltage and provide a fault path. Bonding: connecting all metal parts together to ensure electrical continuity and fault clearing.","cat":"Grounding"},{"id":"c053","term":"Grounding Electrode System","def":"The connection point between the electrical system and earth. Components include ground rods, metal water pipes, concrete-encased electrodes (Ufer), and the building steel.","cat":"Grounding"},{"id":"c054","term":"Grounding Electrode Conductor (GEC)","def":"The conductor connecting the grounded system conductor (neutral) to the grounding electrode. Size is based on the size of the service entrance conductors (Table 250.66).","cat":"Grounding"},{"id":"c055","term":"Equipment Grounding Conductor (EGC)","def":"The conductor connecting non-current-carrying metal parts of equipment to the grounding system. Provides a low-impedance fault return path. Sized per Table 250.122.","cat":"Grounding"},{"id":"c056","term":"Main Bonding Jumper","def":"Connects the equipment grounding conductor to the grounded conductor (neutral) at the service equipment only. This connection is made at the service panel, never at subpanels.","cat":"Grounding"},{"id":"c057","term":"Ground Rod","def":"A driven electrode (typically 8 feet, ¾-inch diameter copper-clad steel) providing earth connection. A single rod must have 25 ohms or less resistance, or a second rod is required.","cat":"Grounding"},{"id":"c058","term":"Separately Derived System","def":"A system with no direct connection to the supply conductors (e.g., a transformer secondary). Requires its own grounding electrode conductor and bonding.","cat":"Grounding"},{"id":"c059","term":"Neutral-Ground Bond","def":"The neutral and ground are bonded together only at the service entrance (main panel) or at a separately derived system. Never at subpanels — this creates parallel paths and shock hazards.","cat":"Grounding"},{"id":"c060","term":"Isolated Ground Receptacle","def":"An orange-triangle receptacle with a dedicated insulated grounding conductor run back to the panel. Reduces electrical noise for sensitive electronic equipment.","cat":"Grounding"},{"id":"c061","term":"Branch Circuit","def":"The circuit conductors between the final overcurrent device and the outlets served. NEC Article 210. Classified by the rating of the overcurrent device (15A, 20A, 30A, etc.).","cat":"Circuits"},{"id":"c062","term":"Feeder","def":"The conductors between the service equipment and the final branch circuit overcurrent device. NEC Article 215. Sized for the calculated load plus applicable demand factors.","cat":"Circuits"},{"id":"c063","term":"Service","def":"The conductors and equipment connecting the utility supply to the premises wiring. NEC Article 230. Only one service per building (with exceptions).","cat":"Circuits"},{"id":"c064","term":"Service Entrance Conductors","def":"The conductors from the service point to the service disconnecting means. Sized to carry the calculated load. Protected by the main breaker.","cat":"Circuits"},{"id":"c065","term":"General Lighting Load (220.12)","def":"Calculated at 3 VA per square foot for dwellings. This is a minimum — actual load may require more. Used in service and feeder calculations.","cat":"Circuits"},{"id":"c066","term":"Small Appliance Circuits (210.11(C)(1))","def":"A minimum of two 20-amp small appliance branch circuits are required for the kitchen and dining areas of a dwelling. No other outlets may be connected to these circuits.","cat":"Circuits"},{"id":"c067","term":"Bathroom Circuit (210.11(C)(3))","def":"At least one 20-amp branch circuit required for bathroom receptacles. May serve one or more bathrooms but no other outlets.","cat":"Circuits"},{"id":"c068","term":"Laundry Circuit (210.11(C)(2))","def":"At least one 20-amp branch circuit required for the laundry area. Dedicated to laundry equipment receptacles.","cat":"Circuits"},{"id":"c069","term":"GFCI Protection (210.8)","def":"Required in bathrooms, kitchens (within 6 feet of sink), garages, outdoors, basements, crawl spaces, boathouses, laundry areas, and near pools and hot tubs.","cat":"Circuits"},{"id":"c070","term":"AFCI Protection (210.12)","def":"Required for most 15A and 20A branch circuits in dwelling unit bedrooms, living rooms, kitchens, hallways, closets, and similar areas. Protects against arc faults that can cause fires.","cat":"Circuits"},{"id":"c071","term":"Receptacle Spacing (210.52)","def":"In dwelling units, receptacles must be placed so no point along a wall is more than 6 feet from a receptacle. Any wall space 2 feet or wider requires a receptacle.","cat":"Circuits"},{"id":"c072","term":"Demand Factor","def":"A percentage applied to reduce the calculated load to reflect that not all loads operate simultaneously. Applied to ranges, dryers, and general lighting per NEC Article 220.","cat":"Circuits"},{"id":"c073","term":"Service Calculation (Article 220)","def":"The process of determining the total electrical load for sizing service entrance conductors and equipment. Applies demand factors to different load categories.","cat":"Circuits"},{"id":"c074","term":"Panel Schedule","def":"A detailed record of each circuit in a panelboard: breaker size, wire size, circuit description, and load. Required for documentation and inspection.","cat":"Circuits"},{"id":"c075","term":"Subpanel","def":"A downstream distribution panel fed from the main panel. Requires four wires (two hots, neutral, ground). Neutral and ground buses must be separated (not bonded).","cat":"Circuits"},{"id":"c076","term":"Overcurrent Protection Device (OCPD)","def":"A device that opens the circuit when current exceeds a set value. Includes circuit breakers and fuses. Sized to protect conductors, not equipment.","cat":"Protection"},{"id":"c077","term":"Circuit Breaker","def":"A reusable OCPD that trips when current exceeds its rating. Types: standard, GFCI, AFCI, dual-function (GFCI+AFCI). Must be accessible without removing panels.","cat":"Protection"},{"id":"c078","term":"Fuse","def":"A one-time-use OCPD containing a metal link that melts at a specific current. Must be replaced after operation. Faster response than breakers for high fault currents.","cat":"Protection"},{"id":"c079","term":"Coordination","def":"Ensuring that the OCPD nearest the fault opens first, leaving upstream devices and circuits unaffected. Achieved by selecting devices with complementary time-current characteristics.","cat":"Protection"},{"id":"c080","term":"Ground Fault Circuit Interrupter (GFCI)","def":"Detects an imbalance of 4-6 milliamps between hot and neutral (indicating current leaking to ground) and trips in 1/40 of a second. Prevents electrocution.","cat":"Protection"},{"id":"c081","term":"Arc Fault Circuit Interrupter (AFCI)","def":"Detects dangerous arc patterns in a circuit and trips before ignition occurs. Distinguishes between normal arcs (switch operation) and hazardous arcs (damaged wire).","cat":"Protection"},{"id":"c082","term":"NEC 240.4(D)","def":"Limits the maximum OCPD size for small conductors: #14 copper = 15A, #12 copper = 20A, #10 copper = 30A. Exceptions exist for specific equipment.","cat":"Protection"},{"id":"c083","term":"Overcurrent vs. Overload vs. Short Circuit","def":"Overcurrent is any current exceeding the rated value. Overload is a gradual excess (motor running too hard). Short circuit is a sudden massive excess (conductor-to-conductor fault).","cat":"Protection"},{"id":"c084","term":"NEC Article 430","def":"Covers motor installations. Motor circuits are sized differently than other circuits because of high inrush current at startup.","cat":"Motors"},{"id":"c085","term":"Motor Full-Load Current (FLC)","def":"The current a motor draws at rated horsepower. Found in NEC Tables 430.247-250, NOT from the nameplate. Used for sizing conductors and OCPDs.","cat":"Motors"},{"id":"c086","term":"Motor Branch Circuit Conductor Sizing","def":"Conductors must be at least 125% of the motor's full-load current (FLC). This accounts for continuous duty operation and startup characteristics.","cat":"Motors"},{"id":"c087","term":"Motor Overload Protection","def":"Protects against sustained overcurrent while running. Sized at 115-125% of nameplate full-load amps. Allows startup inrush but trips on continuous overload.","cat":"Motors"},{"id":"c088","term":"Motor Short-Circuit Protection","def":"Protects the branch circuit conductors. Sized per NEC Table 430.52 — typically 250% of FLC for inverse-time breakers, 300% for fuses. Allows startup inrush.","cat":"Motors"},{"id":"c089","term":"Disconnect (Motor)","def":"A means to disconnect the motor and controller from the supply. Must be within sight and within 50 feet of the motor. Must disconnect all ungrounded conductors.","cat":"Motors"},{"id":"c090","term":"Motor Starter","def":"A device that provides controlled starting and stopping of a motor. Includes overload protection. Types: direct-on-line, reduced voltage, variable frequency drive (VFD).","cat":"Motors"},{"id":"c091","term":"Variable Frequency Drive (VFD)","def":"Controls motor speed by adjusting the frequency and voltage of the power supplied. Improves efficiency and provides soft start. Common in HVAC.","cat":"Motors"},{"id":"c092","term":"Transformer Sizing","def":"Rated in VA or kVA. Primary and secondary conductors sized independently. OCPD sized per NEC 450.3 (primary not over 125%, secondary per Table 450.3(B)).","cat":"Motors"},{"id":"c093","term":"NEC Article 440","def":"Covers air conditioning and refrigeration equipment. Similar to Article 430 but uses nameplate rated-load current (RLA) or branch-circuit selection current.","cat":"Motors"},{"id":"c094","term":"Electric Water Heater (Article 422)","def":"A continuous load (operates for 3+ hours). Branch circuit must be rated at 125% of the nameplate rating. Typically requires a dedicated 30A circuit.","cat":"Motors"},{"id":"c095","term":"Lockout/Tagout (LOTO)","def":"OSHA procedure ensuring equipment is de-energized and cannot be restarted during maintenance. Lock the disconnect, tag it, verify zero energy, then work.","cat":"Safety"},{"id":"c096","term":"NFPA 70E","def":"Standard for Electrical Safety in the Workplace. Defines shock and arc flash hazard boundaries, PPE requirements, and energized electrical work permits.","cat":"Safety"},{"id":"c097","term":"Arc Flash","def":"A dangerous release of energy caused by an electrical arc through air. Temperatures can exceed 35,000°F. Can cause severe burns, blast injuries, and death.","cat":"Safety"},{"id":"c098","term":"PPE for Electrical Work","def":"Personal Protective Equipment: voltage-rated insulating gloves (with leather protectors), face shield, arc-rated clothing, insulated tools. Selected based on voltage and incident energy.","cat":"Safety"},{"id":"c099","term":"Approach Boundaries (NFPA 70E)","def":"Limited Approach: qualified persons only beyond this point. Restricted Approach: shock hazard, PPE required. Prohibited Approach: equivalent to direct contact.","cat":"Safety"},{"id":"c100","term":"Qualified Person","def":"One who has demonstrated skills and knowledge related to the construction and operation of electrical equipment and has received safety training on the hazards involved.","cat":"Safety"},{"id":"c101","term":"OSHA Electrical Standards","def":"29 CFR 1926 (construction) and 1910 (general industry). Cover installation, maintenance, and use of electrical equipment. Violations carry fines and work stoppages.","cat":"Safety"},{"id":"c102","term":"Assured Grounding Conductor Program","def":"An OSHA-accepted alternative to GFCI protection on construction sites. Requires visual inspection, continuity testing, and documentation of grounding equipment.","cat":"Safety"},{"id":"c103","term":"Temporary Wiring (Article 590)","def":"Wiring for construction sites and temporary events. Permits are required. Must have GFCI protection. Must be removed when the purpose is served.","cat":"Safety"},{"id":"c104","term":"Working De-Energized","def":"The default requirement: circuits should be de-energized before work begins. Energized work requires justification, an energized work permit, and proper PPE.","cat":"Safety"},{"id":"c105","term":"Electrical Shock Hazards","def":"Current, not voltage, kills. 1 mA is perceptible, 10-20 mA causes muscle lock (can't let go), 75-100 mA can cause ventricular fibrillation. Wet conditions reduce body resistance.","cat":"Safety"},{"id":"c106","term":"Dwelling Unit Service Calculation","def":"General lighting (3 VA/sq ft) + small appliance circuits (3,000 VA) + laundry (1,500 VA) + appliance nameplate loads, then apply demand factors per Table 220.42.","cat":"Calculations"},{"id":"c107","term":"Range Demand Factor (Table 220.55)","def":"One household range rated up to 12 kW uses a demand of 8 kW. Multiple ranges reduce further. Reduces the calculated load significantly.","cat":"Calculations"},{"id":"c108","term":"Dryer Demand (220.54)","def":"5,000 watts or nameplate, whichever is larger, for a single household dryer. Multiple dryers use demand factors from Table 220.54.","cat":"Calculations"},{"id":"c109","term":"Voltage Drop Calculation","def":"VD = (2 × K × I × D) / CM. K = resistivity constant (copper 12.9, aluminum 21.2). I = current. D = distance. CM = circular mil area of conductor.","cat":"Calculations"},{"id":"c110","term":"Conductor Sizing Process","def":"1) Calculate load current. 2) Select conductor ampacity from Table 310.16. 3) Apply derating/adjustment factors. 4) Check voltage drop. 5) Verify OCPD compatibility.","cat":"Calculations"},{"id":"c111","term":"Conduit Sizing","def":"1) Determine the number and type of conductors. 2) Look up each conductor's area from Chapter 9. 3) Calculate total fill. 4) Select conduit from Table 4 that provides adequate fill percentage.","cat":"Calculations"},{"id":"c112","term":"Load Calculation: Commercial","def":"Computed per Article 220 Part IV. Lighting: Table 220.12 (VA/sq ft varies by occupancy). Receptacles: 180 VA each. Apply demand factors per 220.42 and 220.44.","cat":"Calculations"},{"id":"c113","term":"Ohm's Law Wheel","def":"A circular reference showing the relationships: E=IR, I=E/R, R=E/I, P=EI, P=I²R, P=E²/R, I=P/E, E=P/I. The essential tool for all electrical calculations.","cat":"Calculations"},{"id":"c114","term":"Three-Phase Power Formula","def":"P = E × I × √3 × PF for three-phase loads. The √3 (1.732) factor accounts for the phase relationship between the three conductors.","cat":"Calculations"},{"id":"c115","term":"Transformer Turns Ratio","def":"The ratio of primary to secondary windings determines the voltage transformation. Np/Ns = Ep/Es. A 10:1 ratio steps 480V down to 48V.","cat":"Calculations"},{"id":"c116","term":"NEC Table 310.16","def":"The most-referenced NEC table. Lists allowable ampacities of insulated conductors based on conductor size, insulation temperature rating, and conductor material.","cat":"Calculations"}],"questions":[{"cat":"Calculations","stem":"A dwelling is 2,000 sq ft. The general lighting load is:","choices":["10,000 VA","6,000 VA","2,000 VA","4,000 VA"],"answer":1,"label":"Lighting calculation","why":"3 VA × 2,000 sq ft = 6,000 VA per NEC 220.12.","id":"q079","n":79},{"cat":"Circuits","stem":"The general lighting load for a dwelling unit is calculated at:","choices":["3 VA per square foot","10 VA per square foot","5 VA per square foot","1.5 VA per square foot"],"answer":0,"label":"Dwelling lighting load","why":"NEC Table 220.12 specifies 3 VA per square foot for dwelling units, applied to the total habitable square footage.","id":"q049","n":49},{"cat":"Grounding","stem":"The neutral and ground conductors should be bonded together at:","choices":["Every subpanel","The service entrance panel only (and at separately derived systems)","The last receptacle on the circuit","Every junction box"],"answer":1,"label":"Neutral-ground bond location","why":"The neutral-ground bond is made only at the service equipment (main panel) or at a separately derived system. Bonding at subpanels creates parallel return paths.","id":"q041","n":41},{"cat":"Motors","stem":"Motor branch circuit conductors must be sized at a minimum of:","choices":["The same size as the service entrance conductors","100% of the motor FLC","125% of the motor full-load current from NEC tables","150% of the nameplate amps"],"answer":2,"label":"Motor conductor sizing 125%","why":"NEC 430.22: motor branch circuit conductors must carry at least 125% of the motor's full-load current (from NEC tables, not nameplate).","id":"q064","n":64},{"cat":"NEC General","stem":"The NEC is published by:","choices":["OSHA","NFPA (National Fire Protection Association)","IEEE","The Department of Energy"],"answer":1,"label":"NEC publisher","why":"The NEC is NFPA 70, published by the National Fire Protection Association and updated every three years.","id":"q021","n":21},{"cat":"Protection","stem":"A GFCI detects an imbalance of approximately ___ milliamps and trips:","choices":["50-100","20-30","0.5-1","4-6"],"answer":3,"label":"GFCI trip threshold","why":"GFCIs detect a 4-6 mA imbalance between hot and neutral and trip in about 1/40 of a second to prevent electrocution.","id":"q059","n":59},{"cat":"Safety","stem":"Before working on an electrical circuit, the FIRST step in LOTO is:","choices":["Have a coworker watch the panel","Start working and lock out if interrupted","Notify affected employees, de-energize the circuit, lock out the disconnect, and verify zero energy","Put on PPE"],"answer":2,"label":"LOTO procedure","why":"LOTO requires notification, de-energizing, locking the disconnect, tagging it, and verifying zero energy with a tested meter before any work begins.","id":"q069","n":69},{"cat":"Theory","stem":"A 120V circuit draws 10 amps. The resistance is:","choices":["120 ohms","1,200 ohms","12 ohms","1.2 ohms"],"answer":2,"label":"Ohm's Law: R=E/I","why":"R = E/I = 120V / 10A = 12 ohms.","id":"q001","n":1},{"cat":"Wiring","stem":"NM cable (Romex) may NOT be used in:","choices":["A building exceeding three floors above grade","A two-story residence","A single-family dwelling","A one-story detached garage"],"answer":0,"label":"NM cable limitations","why":"NM cable is limited to Types III, IV, and V construction and cannot be used in buildings exceeding three floors above grade (NEC 334.10).","id":"q031","n":31},{"cat":"Calculations","stem":"What is the demand load for a single 12 kW household range per Table 220.55?","choices":["6 kW","10 kW","8 kW","12 kW"],"answer":2,"label":"Range demand factor","why":"Table 220.55, Column C: one range up to 12 kW has a demand of 8 kW. This significantly reduces the calculated service load.","id":"q080","n":80}],"meta":{"total":88,"free":10,"split":true}};
